// Free pre-filter — drop old mail + newsletters/bulk, trim each item.
// Reads {account, priority} from the Tag node and email fields from IMAP.
const CUTOFF = Date.now() - 24 * 60 * 60 * 1000;
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const from = (e.from || '').toString();
  const subject = (e.subject || '').toString();
  const body = (e.snippet || e.textPlain || e.text || '').toString();
  const ts = e.date ? new Date(e.date).getTime() : Date.now();
  if (ts && ts < CUTOFF) continue;
  const headers = JSON.stringify(e.headers || {}).toLowerCase();
  const isBulk = headers.includes('list-unsubscribe') || /no-?reply|newsletter|notifications?@/i.test(from);
  if (isBulk) continue;
  out.push({ json: {
    account: e.account || 'other',
    priority: e.priority || 2,
    from,
    subject,
    snippet: body.replace(/\s+/g, ' ').trim().slice(0, 600),
    date: e.date || null
  } });
}
return out;

// Pair each Haiku response with its email (index-aligned), parse the
// classification, and drop anything triaged as 'ignore'. Output rows ready
// to INSERT into brief_items.
const emails = $('Free Pre-Filter').all();
const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const email = emails[i] ? emails[i].json : {};
  let text = '';
  try { text = all[i].json.content[0].text; } catch (e) {}
  let parsed = { classification: 'fyi', one_line: email.subject || '' };
  try { parsed = JSON.parse(text); } catch (e) {}
  if (parsed.classification === 'ignore') continue;
  out.push({ json: {
    account: email.account || 'other',
    priority: email.priority || 2,
    from: email.from || '',
    subject: email.subject || '',
    one_line: parsed.one_line || email.subject || '',
    classification: parsed.classification || 'fyi'
  } });
}
return out;
